            var h = makeActionHarness({ failTrackerPostComment: true });
            var logs = captureConsole1002(function() {
                assert.doesNotThrow(function() {
                    h.module.reportActionError({ inputFolderPath: 'input/PROJ-123' }, h.tracker, new Error('boom'));
                });
